def logo_data_uri(size: str = "medium") -> str:
    """Return a ``data:`` URI that can be used directly in an HTML <img src=...>."""
    encoded = {
        "small": LOGO_SMALL_B64,
        "medium": LOGO_MEDIUM_B64,
        "large": LOGO_LARGE_B64,
    }.get(size, LOGO_MEDIUM_B64)
    return f"data:image/png;base64,{encoded}"


def logo_image(size: str = "small"):
    """Return a PIL image of the logo (used as the browser-tab favicon)."""
    from PIL import Image  # imported lazily: Pillow ships with Streamlit

    encoded = {
        "small": LOGO_SMALL_B64,
        "medium": LOGO_MEDIUM_B64,
        "large": LOGO_LARGE_B64,
    }.get(size, LOGO_SMALL_B64)
    return Image.open(io.BytesIO(base64.b64decode(encoded)))
